INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('dd38b86d-325f-4243-8f7e-3cb8c47beaae'::uuid, 'card_description', 'A luxurious late Roman residence from the era of Constantine the Great, with a peristyle villa and private baths. Emperor Constantine was born in the nearby city of Naissus.', 'In the eastern suburb of Niš lies Mediana, a luxurious residence from the reign of Constantine the Great, with a villa, baths, granary and water tower, later a rest stop for emperors.', 'teaser-card-s006:dd38b86d-325f-4243-8f7e-3cb8c47beaae:card_description', 'teaser-card-s006 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'b2df569cf3dd36313956a6b1409b7a454f9e3a8c59facbb25415d831a46a9228|2d75e8b8ab8d7abd71e142ae33bf0966c7c9a1f9bbb5b3ecb901cda0f1723c0b|2d75e8b8ab8d7abd71e142ae33bf0966c7c9a1f9bbb5b3ecb901cda0f1723c0b', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the eastern suburb of Niš lies Mediana, a luxurious residence from the reign of Constantine the Great, with a villa, baths, granary and water tower, later a rest stop for emperors."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mediana is in the eastern suburb of Niš [S1]; it is a luxurious residence [S2]; the residence dates to the reign of Constantine the Great [S4]; it has a villa, baths (thermae), granary and water tower [S3]; later emperors used it as a place of rest [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mediana is a luxurious (imperial) residence [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; Mediana lies in the eastern suburb of Niš [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; The residence dates from the reign of Constantine the Great [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; The site has a villa [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; The site has baths [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; The site has a granary [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; The site has a water tower [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]; The residence was later a rest stop for emperors [SUPPORTED: https://en.wikipedia.org/wiki/Mediana]"}]'::jsonb),
    ('ddbaa0c7-7d30-45fa-ab80-71b0d49d8dec'::uuid, 'card_description', 'Waman Pirqa lies in the Ayacucho Region, Lucanas Province, Carmen Salcedo District, near Antamarka.', 'In Quechua, Waman Pirqa means falcon wall. Near Antamarka, in the Lucanas Province of the Ayacucho Region, this archaeological site was declared a National Cultural Heritage in 2003.', 'teaser-card-s006:ddbaa0c7-7d30-45fa-ab80-71b0d49d8dec:card_description', 'teaser-card-s006 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '54c8a5869ee83c9927be7d49dd539310f747916997880c6d0de98da71ddfc236|8d43a66b88aa5d92a3e5991b937b5b39a1d6d7b8785a14c451c539814160e2c5|8d43a66b88aa5d92a3e5991b937b5b39a1d6d7b8785a14c451c539814160e2c5', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In Quechua, Waman Pirqa means falcon wall. Near Antamarka, in the Lucanas Province of the Ayacucho Region, this archaeological site was declared a National Cultural Heritage in 2003."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "in Quechua, Waman Pirqa means falcon wall [S1]; it lies near Antamarka [S3]; it is in the Lucanas Province of the Ayacucho Region [S3]; it is an archaeological site [S1]; it was declared a National Cultural Heritage in 2003 [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Waman Pirqa is an archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]; In Quechua, Waman Pirqa means falcon wall [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]; The site is near Antamarka [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]; The site is in the Lucanas Province [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]; The site is in the Ayacucho Region [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]; The site was declared a National Cultural Heritage [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]; The declaration was made in 2003 [SUPPORTED: https://en.wikipedia.org/wiki/Waman_Pirqa]"}]'::jsonb),
    ('dde240ca-5969-4123-a842-e7e235f7566b'::uuid, 'card_description', '5300-4900 BC Bandkeramik farming landscape in the Merzbach Valley. Langweiler revealed 160 houses across eight settlement sites, three enclosures, and a cemetery, a window into Europe''s first farmers.', 'In the Merzbach Valley, Langweiler revealed 160 houses, enclosures and a cemetery of the earliest farming societies in west-central Europe, from 5300-4900 BC, before mining destroyed it.', 'teaser-card-s006:dde240ca-5969-4123-a842-e7e235f7566b:card_description', 'teaser-card-s006 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '19c7338307bae7b3f4ae7b28a001305eae1716f9b1a1580bd6cc99bfeebbf021|170a9da5a47b28b807f52e2749a846f3b80961f3732eca257fb7dacca007b9ce|170a9da5a47b28b807f52e2749a846f3b80961f3732eca257fb7dacca007b9ce', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the Merzbach Valley, Langweiler revealed 160 houses, enclosures and a cemetery of the earliest farming societies in west-central Europe, from 5300-4900 BC, before mining destroyed it."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Langweiler is in the Merzbach Valley [S1]; excavations revealed 160 houses [S2]; excavations revealed enclosures and a cemetery [S2]; the remains belong to the earliest farming societies in west-central Europe [S3]; they date from 5300-4900 BC [S2]; the settlements were recovered before the area was destroyed for mining [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Langweiler is an archaeological site (a group of early farming settlements) in the Merzbach Valley [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]; Excavations at Langweiler revealed 160 houses [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]; Excavations revealed enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]; Excavations revealed a cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]; The remains belong to the earliest farming societies in west-central Europe [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]; The remains date from 5300-4900 BC [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]; Mining later destroyed the site [SUPPORTED: https://en.wikipedia.org/wiki/Langweiler_(archaeological_site)]"}]'::jsonb),
    ('dea9db29-e9cc-4ebc-b01b-e6f3028fbd4f'::uuid, 'card_description', 'Broch on the eastern shore near Golspie in Sutherland, visible beside the A9 road. The entrance passage leads to a guard cell; stairway remains survive within the wall thickness.', 'First mistaken for a burial cairn, the Iron Age broch of Carn Liath near Golspie yielded a whale bone club, a silver fibula, steatite cups and long-handled bone combs.', 'teaser-card-s006:dea9db29-e9cc-4ebc-b01b-e6f3028fbd4f:card_description', 'teaser-card-s006 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '3bb704f2121d8b6644bbc3686118c24d27b5e4a9d84a6c4ebf5a9ce9676c4112|4d4c4d83688e92cbc76ed8ad9faf470b85da369a1c15105a8b343ce506284468|4d4c4d83688e92cbc76ed8ad9faf470b85da369a1c15105a8b343ce506284468', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "First mistaken for a burial cairn, the Iron Age broch of Carn Liath near Golspie yielded a whale bone club, a silver fibula, steatite cups and long-handled bone combs."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it was initially thought to be a burial cairn [S3]; Carn Liath is an Iron Age broch [S1]; it is near Golspie [S1]; finds included a whale bone club, a silver fibula, steatite cups and long-handled bone combs [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Carn Liath is a broch near Golspie [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]; The broch dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]; The broch was first mistaken for a burial cairn [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]; The broch yielded a whale bone club [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]; The broch yielded a silver fibula [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]; The broch yielded steatite cups [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]; The broch yielded long-handled bone combs [SUPPORTED: https://en.wikipedia.org/wiki/Carn_Liath_(broch)]"}]'::jsonb),
    ('df0881e1-4fd6-4d2d-b9de-ffdca718970c'::uuid, 'card_description', 'A Roman-era council house that doubled as a theatre, built in the 2nd century AD. It went through four construction phases before being abandoned in the 4th century.', 'In a corner of Plovdiv''s Roman forum lies the Odeon of Philippopolis, a council house that was also used as a theatre, with orchestra, cavea and a Corinthian skene two stories high.', 'teaser-card-s006:df0881e1-4fd6-4d2d-b9de-ffdca718970c:card_description', 'teaser-card-s006 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '0dab3db64b52361da61485357ac3115289a3a1b4f430b4b0d9cdcfe152362ab0|b72b5b9e43644ba762d6462a751f5491862e276b7c5b637ef24bb7cfab3728af|b72b5b9e43644ba762d6462a751f5491862e276b7c5b637ef24bb7cfab3728af', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In a corner of Plovdiv''s Roman forum lies the Odeon of Philippopolis, a council house that was also used as a theatre, with orchestra, cavea and a Corinthian skene two stories high."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Odeon lies in a corner of Plovdiv''s Roman forum [S5]; it was a council house [S1]; it was also used as a theatre [S2]; it had an orchestra [S6]; it had a cavea [S6]; its skene was in the Corinthian order [S7]; the skene was two stories high [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Odeon of Philippopolis is the council house (bouleuterion) of ancient Plovdiv [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; It lies in a corner of Plovdiv''s Roman forum [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; It was also used as a theatre [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; It has an orchestra [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; It has a cavea [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; It has a skene [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; The skene is in the Corinthian order [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]; The skene is two stories high [SUPPORTED: https://en.wikipedia.org/wiki/Odeon_of_Philippopolis]"}]'::jsonb),
    ('df0e220d-573f-4cfd-92a7-c65f4c690186'::uuid, 'card_description', 'About 270 AD, after several plagues and attacks by Saxon pirates and the reconquering of the region from the Gallic Empire, the Romans abandoned Forum Hadriani.', 'Along the Corbulo-canal in Voorburg lay Forum Hadriani, the northernmost Roman city on the European continent. About 270 AD, after plagues and Saxon pirate attacks, the Romans abandoned it.', 'teaser-card-s006:df0e220d-573f-4cfd-92a7-c65f4c690186:card_description', 'teaser-card-s006 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '8c9fd1df4cda5a2e0856db5d6172457d6353902ff1d75a416557d817360eca2e|e965dcbc1e4a5ab815da717062775ba587d72ce376f12a9fa4049635a59981e6|e965dcbc1e4a5ab815da717062775ba587d72ce376f12a9fa4049635a59981e6', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Along the Corbulo-canal in Voorburg lay Forum Hadriani, the northernmost Roman city on the European continent. About 270 AD, after plagues and Saxon pirate attacks, the Romans abandoned it."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Forum Hadriani lay along the Corbulo-canal [S4]; it lay in Voorburg [S1]; it was the northernmost Roman city on the European continent [S1]; the Romans abandoned it about 270 AD [S5]; the abandonment came after plagues [S5]; the abandonment came after attacks by Saxon pirates [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Forum Hadriani was a Roman city located in Voorburg (Netherlands) [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Hadriani]; Forum Hadriani lay along the Corbulo-canal [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Hadriani]; Forum Hadriani was the northernmost Roman city on the European continent [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Hadriani]; The Romans abandoned Forum Hadriani about 270 AD [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Hadriani]; The abandonment came after plagues [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Hadriani]; The abandonment came after attacks by Saxon pirates [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Hadriani]"}]'::jsonb),
    ('df418ae4-13b2-4bb6-870a-21e53b713526'::uuid, 'card_description', 'At 225 metres — the joint highest point in Northamptonshire — this summit hillfort enclosed about 4.9 hectares within a square ditch and embankment roughly 200 metres across.', 'On the summit of Arbury Hill, the joint highest point in Northamptonshire, lie the vestiges of an Iron Age fort whose date and origin are disputed: a square ditch about 200 metres across.', 'teaser-card-s006:df418ae4-13b2-4bb6-870a-21e53b713526:card_description', 'teaser-card-s006 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'e85b561a0b6bb6861035758ee5e2f0a98fbf976233d3324cc2c356173485fe70|576380845e9ab727a30391cd662464acde63d87e646515e4f310347d877dbbec|576380845e9ab727a30391cd662464acde63d87e646515e4f310347d877dbbec', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the summit of Arbury Hill, the joint highest point in Northamptonshire, lie the vestiges of an Iron Age fort whose date and origin are disputed: a square ditch about 200 metres across."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Arbury Hill has a summit [S3]; Arbury Hill is the joint highest point in Northamptonshire [S1]; vestiges of an Iron Age fort lie on the summit [S3]; the fort''s date and origin are disputed [S3]; the remains take the form of a square ditch [S4]; the remains are about 200 metres across [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The remains of an Iron Age fort lie on the summit of Arbury Hill (Northamptonshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Arbury_Hill]; Arbury Hill is the joint highest point in Northamptonshire [SUPPORTED: https://en.wikipedia.org/wiki/Arbury_Hill]; Only vestiges of the fort remain [SUPPORTED: https://en.wikipedia.org/wiki/Arbury_Hill]; The fort''s date and origin are disputed [SUPPORTED: https://en.wikipedia.org/wiki/Arbury_Hill]; The remains take the form of a square ditch [SUPPORTED: https://en.wikipedia.org/wiki/Arbury_Hill]; The square ditch is about 200 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Arbury_Hill]"}]'::jsonb),
    ('df6aa58a-16ff-416f-9112-75f8e2ea5c11'::uuid, 'card_description', 'A 2.5 km Celtic ringwall from 500 BC, built as a Murus Gallicus with timber-laced stonework. It was deliberately demolished shortly after construction -- no one knows why.', 'An apparently demolished stone wall rings the Heidenmauer, about 700 metres from north to south, around a settlement partly open for centuries and partly unseen until it was excavated.', 'teaser-card-s006:df6aa58a-16ff-416f-9112-75f8e2ea5c11:card_description', 'teaser-card-s006 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '9997921dd2cb86600261f6631da99b5dfd283afbba7bd74312faf26a68f44baf|63b4bbf872f199b7fc41859c37df23dd2951fcdfa7e2a6a9ab74ee778ac0f285|63b4bbf872f199b7fc41859c37df23dd2951fcdfa7e2a6a9ab74ee778ac0f285', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "An apparently demolished stone wall rings the Heidenmauer, about 700 metres from north to south, around a settlement partly open for centuries and partly unseen until it was excavated."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "a stone wall forms the ring of the Heidenmauer [S3]; the wall is apparently demolished (hedge kept) [S3]; the site measures about 700 metres from north to south [S5]; the wall surrounds a settlement [S4]; part of the settlement lay open for centuries [S4]; part of the settlement was not uncovered until it was excavated [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Heidenmauer (Palatinate) is a ringwork: a ring wall enclosing a settlement [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]; The ring is formed by a stone wall [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]; The stone wall appears to have been demolished [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]; The Heidenmauer measures about 700 metres from north to south [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]; The wall surrounds a settlement [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]; Part of the settlement remains lay open for centuries [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]; Part of the settlement remains was unseen until it was excavated [SUPPORTED: https://en.wikipedia.org/wiki/Heidenmauer_(Palatinate)]"}]'::jsonb),
    ('dfab4856-d41f-4228-a94a-e32822c59a0f'::uuid, 'card_description', 'Built 7th–4th centuries BC near Northampton, this fort''s wooden rampart burned hot enough to vitrify the stone beneath. The deep surrounding ditch has survived to the present day.', 'In about 1883 ironstone digging began at Hunsbury Hill, an Iron Age hill fort, and revealed up to 300 pits: iron weapons, bronze brooches, glass and around 159 quern-stones came to light.', 'teaser-card-s006:dfab4856-d41f-4228-a94a-e32822c59a0f:card_description', 'teaser-card-s006 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '10bf41eda6d1f93ad44b47b4214b09d6d6f12372ac52d29119c7b7671a5c461b|dfcb0976c76277c5e93a1e11d89372830d8595a120c9db2fa9fda0a2b0e2d855|dfcb0976c76277c5e93a1e11d89372830d8595a120c9db2fa9fda0a2b0e2d855', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In about 1883 ironstone digging began at Hunsbury Hill, an Iron Age hill fort, and revealed up to 300 pits: iron weapons, bronze brooches, glass and around 159 quern-stones came to light."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "ironstone extraction began at Hunsbury Hill in about 1883 [S4]; Hunsbury Hill is an Iron Age hill fort [S1]; the work revealed up to 300 pits [S5]; the finds included iron weapons [S6]; the finds included bronze brooches [S6]; the finds included glass [S6]; the finds included around 159 quern-stones [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Hunsbury Hill is an Iron Age hill fort (near Northampton, England) [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]; Ironstone digging began at Hunsbury Hill in about 1883 [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]; The ironstone digging revealed up to 300 pits [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]; Iron weapons came to light [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]; Bronze brooches came to light [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]; Glass came to light [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]; Around 159 quern-stones came to light [SUPPORTED: https://en.wikipedia.org/wiki/Hunsbury_Hill]"}]'::jsonb),
    ('dfc58d6f-44da-4159-b6e0-5fee86690841'::uuid, 'card_description', 'A 2,000-year-old underground quarry that supplied stone for cathedrals across the region. The soft limestone was prized for its carvability in door and window surrounds.', '2,000 years of quarrying hollowed out Beer Quarry Caves in Devon. In the Roman section, cut by hand with picks and wooden wedges, large arches still hold up the limestone roof.', 'teaser-card-s006:dfc58d6f-44da-4159-b6e0-5fee86690841:card_description', 'teaser-card-s006 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '27c9dc8b03751d2a3bf03ce2c09da5a36bf9495759c19ad04c1d44ef07d33c50|5408da355285c8e766866605a449fa87f8ec2f6046a5da19da76d9904e90d12c|5408da355285c8e766866605a449fa87f8ec2f6046a5da19da76d9904e90d12c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "2,000 years of quarrying hollowed out Beer Quarry Caves in Devon. In the Roman section, cut by hand with picks and wooden wedges, large arches still hold up the limestone roof."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Beer Quarry Caves resulted from 2,000 years of quarrying [S2]; the caves are in Devon [S1]; there is a Roman section [S4]; the Roman section was excavated by hand with picks and wooden wedges [S4]; large arches support the roof of the Roman section [S4]; the roof is limestone (the complex is a limestone underground complex) [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Beer Quarry Caves is a man-made underground quarry complex in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]; The caves were hollowed out by 2,000 years of quarrying [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]; The caves include a Roman section [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]; The Roman section was cut by hand [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]; The Roman section was cut with picks and wooden wedges [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]; Large arches still hold up the roof in the Roman section [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]; The roof is limestone [SUPPORTED: https://en.wikipedia.org/wiki/Beer_Quarry_Caves]"}]'::jsonb),
    ('e282f2a0-5fbd-445b-81dc-63432936feff'::uuid, 'card_description', NULL, 'At the foot of Amazmaz, on the Adrar plateau, a chain of ponds hides among rocks and rushes, and rock paintings on the slopes show the waters were used for thousands of years.', 'teaser-card-s006:e282f2a0-5fbd-445b-81dc-63432936feff:card_description', 'teaser-card-s006 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'bc2101e1611941ae99bd141274004b25e7ccc77d5fea3340bd53bce39953feb7|7fc2cb2ab1c7c39e4e8aceb3e0049b0cfcdcb024e71816112ff42dadd5819491|7fc2cb2ab1c7c39e4e8aceb3e0049b0cfcdcb024e71816112ff42dadd5819491', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At the foot of Amazmaz, on the Adrar plateau, a chain of ponds hides among rocks and rushes, and rock paintings on the slopes show the waters were used for thousands of years."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "a chain of ponds lies at the foot of Amazmaz [S2]; Amazmaz is on the Adrar plateau [S1]; the ponds are hidden among rocks [S2]; the ponds are surrounded by rushes [S2]; there are rock paintings on the slopes [S2]; the rock paintings show the waters were used for thousands of years [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Amazmaz is a rock-art site with ponds (gueltas) at the foot of the Amazmaz elevation on the Adrar plateau in Mauritania [SUPPORTED: https://en.wikipedia.org/wiki/Amazmaz]; At the foot of Amazmaz lies a chain of ponds [SUPPORTED: https://en.wikipedia.org/wiki/Amazmaz]; The ponds are hidden among rocks [SUPPORTED: https://en.wikipedia.org/wiki/Amazmaz]; The ponds are surrounded by rushes [SUPPORTED: https://en.wikipedia.org/wiki/Amazmaz]; There are rock paintings on the slopes by the waters [SUPPORTED: https://en.wikipedia.org/wiki/Amazmaz]; The rock paintings show the waters were used for thousands of years [SUPPORTED: https://en.wikipedia.org/wiki/Amazmaz]"}]'::jsonb),
    ('e286fd8d-fb39-4196-be34-c32545c512b0'::uuid, 'card_description', 'A Maya city that peaked in the 3rd century BC with some of the largest pyramids ever built in the Maya world. It was abandoned, reoccupied, and abandoned again.', 'In the north of El Petén lie the white roads of El Mirador, 40 meters wide, and monumental architecture up to 72 meters high. This Maya settlement flourished from about the 6th century BC.', 'teaser-card-s006:e286fd8d-fb39-4196-be34-c32545c512b0:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'c1f05a582d99d1e5b5d45a6a915e15940a2990d9388faf40c5787433d1c33a75|9d3404e5e39105d2c3950ac75712a3623f647b1a24150a873ab795516d3b90a6|9d3404e5e39105d2c3950ac75712a3623f647b1a24150a873ab795516d3b90a6', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the north of El Petén lie the white roads of El Mirador, 40 meters wide, and monumental architecture up to 72 meters high. This Maya settlement flourished from about the 6th century BC."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "El Mirador lies in the north of El Peten [S1]; El Mirador has white roads [S2]; the white roads are 40 meters wide [S2]; El Mirador has monumental architecture up to 72 meters high [S6]; El Mirador is a Maya settlement [S1]; it flourished from about the 6th century BC [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "El Mirador is a Maya settlement in the north of El Petén, Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]; El Mirador lies in the north of El Petén [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]; El Mirador has white roads [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]; The white roads are 40 meters wide [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]; El Mirador has monumental architecture [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]; The monumental architecture reaches up to 72 meters high [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]; El Mirador flourished from about the 6th century BC [SUPPORTED: https://en.wikipedia.org/wiki/El_Mirador]"}]'::jsonb),
    ('e355bfda-5a11-4b50-813f-8212abdd0009'::uuid, 'card_description', 'A 40 m cave once shared by cave bears and Paleolithic humans. Bone tools made from bear skulls, dated to 27,000 years ago, were found inside.', 'Cave bears sheltered in the Tischofer Cave, and tools made of their bones, dated to about 27,000 to 28,000 years ago, make it the oldest known uncontested site of human occupation in Tyrol.', 'teaser-card-s006:e355bfda-5a11-4b50-813f-8212abdd0009:card_description', 'teaser-card-s006 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '4c54801b01d4fa972c1d17778ce3ff09ab9ff00f9a077ac6bf7ab86d6c49edef|57376e2c6896af80e966980c1ae763a72cf6b9cafe50b28b80673ece97954e45|57376e2c6896af80e966980c1ae763a72cf6b9cafe50b28b80673ece97954e45', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cave bears sheltered in the Tischofer Cave, and tools made of their bones, dated to about 27,000 to 28,000 years ago, make it the oldest known uncontested site of human occupation in Tyrol."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "cave bears used the Tischofer Cave as shelter [S2]; tools made of cave bear bones were found there [S3]; the tools are dated to about 27,000 to 28,000 years ago [S3]; that dating makes it the oldest known uncontested site of human occupation in Tyrol [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Tischofer Cave is a cave in Austria that was a Paleolithic shelter of cave bears and a site of early human occupation [SUPPORTED: https://en.wikipedia.org/wiki/Tischofer_Cave]; The cave lies in Tyrol [SUPPORTED: https://en.wikipedia.org/wiki/Tischofer_Cave]; Cave bears sheltered in the Tischofer Cave [SUPPORTED: https://en.wikipedia.org/wiki/Tischofer_Cave]; Tools made of cave bear bones were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Tischofer_Cave]; The bone tools are dated to about 27,000 to 28,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Tischofer_Cave]; That dating makes Tischofer Cave the oldest known uncontested site of human occupation in Tyrol [SUPPORTED: https://en.wikipedia.org/wiki/Tischofer_Cave]"}]'::jsonb),
    ('e3e42f8a-9a6e-438b-bd2f-69b883334600'::uuid, 'card_description', 'A Paleolithic cave ranked among the most significant in Europe. Two Neanderthal skeletons—Spy I and Spy II—found here were among the first ever identified.', 'In 1886 Spy Cave yielded Neanderthal fossils of excellent quality. It also gave up almost 12,000 Pleistocene faunal remains, among them bones of mammoth, cave hyena and woolly rhinoceros.', 'teaser-card-s006:e3e42f8a-9a6e-438b-bd2f-69b883334600:card_description', 'teaser-card-s006 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'a4db62e9b6eb29a4731bcb4e8fc2bf915837d733d5d9d1cc1d30f822e4840338|2e3678d8839bcbdc1175a4ecc5100213a389d3fc0222039eafacc3cabf155a37|2e3678d8839bcbdc1175a4ecc5100213a389d3fc0222039eafacc3cabf155a37', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In 1886 Spy Cave yielded Neanderthal fossils of excellent quality. It also gave up almost 12,000 Pleistocene faunal remains, among them bones of mammoth, cave hyena and woolly rhinoceros."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Neanderthal fossils were found in Spy Cave [S3]; they were found in 1886 [S3]; the fossils are of excellent quality [S3]; almost 12,000 Pleistocene faunal remains were found [S6]; they include bones of mammoth [S6]; they include bones of cave hyena [S6]; they include bones of woolly rhinoceros [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Spy Cave is a Palaeolithic cave site with Neanderthal remains in Belgium [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]; Neanderthal fossils were found at Spy Cave in 1886 [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]; The Neanderthal fossils were of excellent quality [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]; Almost 12,000 Pleistocene faunal remains were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]; The faunal remains include mammoth bones [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]; The faunal remains include cave hyena bones [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]; The faunal remains include woolly rhinoceros bones [SUPPORTED: https://en.wikipedia.org/wiki/Spy_Cave]"}]'::jsonb),
    ('e4c7f9de-4dbb-47bc-9586-216f486ac86a'::uuid, 'card_description', 'A 3rd-century BC Macedonian tomb with a monumental painted facade depicting scenes of judgment in the afterlife. Two vaulted chambers survive under the tumulus.', 'Behind a disproportionately large painted facade, 8.68 m wide and 8.6 m high, the Tomb of Judgement keeps two vaulted chambers. Road builders came upon it at Lefkadia in 1954.', 'teaser-card-s006:e4c7f9de-4dbb-47bc-9586-216f486ac86a:card_description', 'teaser-card-s006 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '33a38a92d6bfebd26d6287a3f5ac8dae804b422bc70b0dae1048989fc19d0652|d068bc6b25152e42a065c6ec75f4f3bb6c11068be3a0564a785c431f44d072ac|d068bc6b25152e42a065c6ec75f4f3bb6c11068be3a0564a785c431f44d072ac', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Behind a disproportionately large painted facade, 8.68 m wide and 8.6 m high, the Tomb of Judgement keeps two vaulted chambers. Road builders came upon it at Lefkadia in 1954."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the tomb has a painted facade [S1]; the facade is disproportionately large [S3]; the facade is 8.68 m wide [S5]; the facade is 8.6 m high [S5]; the Tomb of Judgement consists of two vaulted chambers [S3]; it was discovered during road construction [S6]; it lies at Lefkadia [S1]; it was discovered in 1954 [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Tomb of Judgement is an ancient Macedonian tomb at Lefkadia, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]; The tomb has a painted facade [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]; The facade is disproportionately large [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]; The facade is 8.68 m wide [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]; The facade is 8.6 m high [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]; Behind the facade the tomb has two vaulted chambers [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]; The tomb was found by road builders [SUPPORTED: https://topostext.org/place/407221GJud]; The tomb was found in 1954 [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Judgement,_Lefkadia]"}]'::jsonb),
    ('e6a32ed2-57ae-48ba-ad7c-bbeeba5f31f1'::uuid, 'card_description', 'A small cave shrine dedicated to Apollo, Pan, and the Nymphs, occupied from the 6th to 2nd century BC. One devotee carved elaborate reliefs directly into the cave walls.', 'Near the top of a spur of Mount Hymettus, the small Vari Cave was a shrine to Apollo, Pan and the Nymphs, and inscriptions inside say Archedemus of Thera built the sanctuary.', 'teaser-card-s006:e6a32ed2-57ae-48ba-ad7c-bbeeba5f31f1:card_description', 'teaser-card-s006 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'd7c0a49b4a6eb619c5a5e4a663be0e97d8a8151d3dafa34d7f4edea5cb04b707|26e230cc28a189e3570403e06b81dcd84a21f418c668082be6a03583a1715e46|26e230cc28a189e3570403e06b81dcd84a21f418c668082be6a03583a1715e46', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near the top of a spur of Mount Hymettus, the small Vari Cave was a shrine to Apollo, Pan and the Nymphs, and inscriptions inside say Archedemus of Thera built the sanctuary."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the cave lies near the top of a spur of Mount Hymettus [S7]; Vari Cave is small [S1]; it was a shrine to Apollo, Pan and the Nymphs [S2]; inscriptions were found inside the cave [S8]; the inscriptions say Archedemus of Thera built the sanctuary [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Vari Cave in Greece is a cave used as a shrine (a cave sanctuary) [SUPPORTED: https://en.wikipedia.org/wiki/Vari_Cave]; The cave lies near the top of a spur of Mount Hymettus [SUPPORTED: https://en.wikipedia.org/wiki/Vari_Cave]; The Vari Cave is small [SUPPORTED: https://en.wikipedia.org/wiki/Vari_Cave]; The shrine was dedicated to Apollo, Pan and the Nymphs [SUPPORTED: https://en.wikipedia.org/wiki/Vari_Cave]; Inscriptions inside the cave say Archedemus of Thera built the sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Vari_Cave]"}]'::jsonb),
    ('e765ff49-b186-4cf0-b32a-94a3aa453de9'::uuid, 'card_description', 'A 6-metre Iron Age boat carved from a single oak trunk, dating to 457–300 BC. Its bowed bow and slotted stern board show sophisticated woodworking for river transport.', 'Found on the banks of the River Witham in 2001, the Fiskerton Log Boat was worked from a single oak trunk that still bears axe marks, then deliberately sunk as an offering.', 'teaser-card-s006:e765ff49-b186-4cf0-b32a-94a3aa453de9:card_description', 'teaser-card-s006 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '5e5d1eff6403d88a4f82ef19733562f164d08f2a26f1b60c6cde0540f862a8a4|90eacd4a37ffc621547a7f56e67e4047360860f66ca077cf1cc5838144cd968c|90eacd4a37ffc621547a7f56e67e4047360860f66ca077cf1cc5838144cd968c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Found on the banks of the River Witham in 2001, the Fiskerton Log Boat was worked from a single oak trunk that still bears axe marks, then deliberately sunk as an offering."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Fiskerton Log Boat was found on the banks of the River Witham [S1]; it was found in 2001 [S1]; it was worked from a single oak trunk [S2, S4]; it still bears axe marks [S2]; it was deliberately sunk as an offering [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Fiskerton Log Boat in England is an ancient log boat (a dugout boat) [SUPPORTED: https://en.wikipedia.org/wiki/Fiskerton_log_boat]; It was found on the banks of the River Witham [SUPPORTED: https://en.wikipedia.org/wiki/Fiskerton_log_boat]; It was found in 2001 [SUPPORTED: https://en.wikipedia.org/wiki/Fiskerton_log_boat]; It was worked from a single oak trunk [SUPPORTED: https://en.wikipedia.org/wiki/Fiskerton_log_boat]; The boat still bears axe marks [SUPPORTED: https://en.wikipedia.org/wiki/Fiskerton_log_boat]; The boat was deliberately sunk as an offering [SUPPORTED: https://en.wikipedia.org/wiki/Fiskerton_log_boat]"}]'::jsonb),
    ('e7fe6e06-b47a-4128-b99d-e07645b60837'::uuid, 'card_description', 'A Gallo-Roman bridge-aqueduct from the 2nd century AD that carried water across a valley on stone arches. Its design influenced medieval bridge-building in the region.', 'Arches still stride through the Valley of the Arennes: the Gallo-Roman Aqueduct of Luynes, one of the best preserved of the Northern aqueducts and a historical monument since 1862.', 'teaser-card-s006:e7fe6e06-b47a-4128-b99d-e07645b60837:card_description', 'teaser-card-s006 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'c84bf70014069d847fbdbf7222fc2660b9b6e84fcb5de65592afdaac63c12411|99d8b3dfbec5114445472e459478e941dc43ea285fd5a676c8c7f7658fdb9bad|99d8b3dfbec5114445472e459478e941dc43ea285fd5a676c8c7f7658fdb9bad', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Arches still stride through the Valley of the Arennes: the Gallo-Roman Aqueduct of Luynes, one of the best preserved of the Northern aqueducts and a historical monument since 1862."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "arches of the aqueduct remain standing [S2]; the visible portion passes through the Valley of the Arennes [S7]; the aqueduct is Gallo-Roman [S1]; it is one of the best preserved of the Northern aqueducts [S3]; it has been a historical monument since 1862 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Aqueduct of Luynes is a Gallo-Roman (bridge) aqueduct at Luynes, France [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Luynes]; Arches of the aqueduct still stand [SUPPORTED: https://fr.wikipedia.org/wiki/Aqueduc_de_Luynes]; The surviving arches run through the Valley of the Arennes [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Luynes]; It is one of the best preserved of the Northern aqueducts [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Luynes]; It has been a historical monument since 1862 [SUPPORTED: https://fr.wikipedia.org/wiki/Aqueduc_de_Luynes]"}]'::jsonb),
    ('e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e'::uuid, 'card_description', 'A Roman-era sand quarry that became an archaeological site. Pottery and a Roman well reveal a substantial settlement nobody expected to find in a sand pit.', 'Pottery and a Roman well came to light at Double Arches Pit, a former sand quarry near Heath and Reach in Bedfordshire, opened in 1916 and now a Site of Special Scientific Interest.', 'teaser-card-s006:e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e:card_description', 'teaser-card-s006 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'a74228fe72daf14dcaf105e8cabe0e9432a65eb96b14b14c93618174b7f79f73|e15093a123f288823cf8c886946c24131238c2e428705e2511762580b74415b9|e15093a123f288823cf8c886946c24131238c2e428705e2511762580b74415b9', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Pottery and a Roman well came to light at Double Arches Pit, a former sand quarry near Heath and Reach in Bedfordshire, opened in 1916 and now a Site of Special Scientific Interest."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "pottery was discovered at Double Arches Pit [S3]; a Roman well was discovered there [S3]; Double Arches Pit was a sand quarry [S1]; it is near Heath and Reach [S1]; it is in Bedfordshire [S1]; the pit was opened in 1916 [S4]; it is now a Site of Special Scientific Interest [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Double Arches Pit is a sand quarry near Heath and Reach [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]; Double Arches Pit lies in Bedfordshire [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]; The quarry is a former one, no longer worked [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]; Pottery came to light at Double Arches Pit [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]; A Roman well came to light at Double Arches Pit [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]; The pit was opened in 1916 [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]; Double Arches Pit is now a Site of Special Scientific Interest [SUPPORTED: https://en.wikipedia.org/wiki/Double_Arches_Pit]"}]'::jsonb),
    ('eaeff16a-cb40-43bb-b667-9d1d1cb691f9'::uuid, 'card_description', 'A 7th-century BC Celtic hilltop fortification just 9 km from the Heuneburg, a major Hallstatt-era power center. It may have served as a cult or assembly site.', 'On a spur at the edge of the Swabian Jura, the main rampart of Alte Burg still rises up to 12 meters above its moat, closing off a Celtic hillfort that may have been a cult or assembly site.', 'teaser-card-s006:eaeff16a-cb40-43bb-b667-9d1d1cb691f9:card_description', 'teaser-card-s006 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '0f9d4a2567b0adbd5c6889af179b96b90893500c23452ec05b14baea4044561a|4c95d1056965911c9c7b2567a078613c7e85383db5a264c091aa35e6f82bf311|4c95d1056965911c9c7b2567a078613c7e85383db5a264c091aa35e6f82bf311', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a spur at the edge of the Swabian Jura, the main rampart of Alte Burg still rises up to 12 meters above its moat, closing off a Celtic hillfort that may have been a cult or assembly site."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Alte Burg lies on a spur [S4]; it lies at the edge of the Swabian Jura [S4]; its main rampart still rises up to 12 meters above the moat [S6]; the main rampart closes off the site [S5]; Alte Burg is a Celtic hillfort [S1]; it may have been a cult or assembly site (hedge kept) [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Alte Burg near Langenenslingen, Germany, is a Celtic hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Alte_Burg_(Langenenslingen)]; The hillfort lies on a spur [SUPPORTED: https://en.wikipedia.org/wiki/Alte_Burg_(Langenenslingen)]; The spur is at the edge of the Swabian Jura [SUPPORTED: https://en.wikipedia.org/wiki/Alte_Burg_(Langenenslingen)]; The main rampart still rises up to 12 meters above its moat [SUPPORTED: https://en.wikipedia.org/wiki/Alte_Burg_(Langenenslingen)]; The main rampart closes off the hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Alte_Burg_(Langenenslingen)]; The hillfort may have been a cult or assembly site [SUPPORTED: https://en.wikipedia.org/wiki/Alte_Burg_(Langenenslingen)]"}]'::jsonb),
    ('eb347510-7433-420e-aee8-adb0cdec43aa'::uuid, 'card_description', 'An Iron Age earthwork enclosing coastal hillside along the Jurassic Coast. Its main rampart and ditch run over 2 km parallel to the shoreline.', 'On the Jurassic Coast near Lulworth Cove, the Iron Age rampart of Bindon Hill runs for over 2 km along a ridge, enclosing about 110 ha, likely a vast pasture rather than a hill fort.', 'teaser-card-s006:eb347510-7433-420e-aee8-adb0cdec43aa:card_description', 'teaser-card-s006 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '32bad6297d3a550701c4503f89e1192584521e9f617ddb2a749bf0e21f6a2546|2edffb5ca5158c71224550cbaabaf8b1d46c8237e0eb40addf5902bd10d5aa1c|2edffb5ca5158c71224550cbaabaf8b1d46c8237e0eb40addf5902bd10d5aa1c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the Jurassic Coast near Lulworth Cove, the Iron Age rampart of Bindon Hill runs for over 2 km along a ridge, enclosing about 110 ha, likely a vast pasture rather than a hill fort."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "on the Jurassic Coast [S1]; near Lulworth Cove [S1]; the earthwork is Iron Age [S1]; the rampart runs for over 2 km along a ridge [S3]; it encloses about 110 ha [S7]; it was likely a vast pasture rather than a hill fort (hedged) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Bindon Hill is an Iron Age earthwork enclosure (rampart) near Lulworth Cove, England [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]; The site is on the Jurassic Coast [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]; The rampart dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]; The rampart runs for over 2 km [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]; The rampart runs along a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]; It encloses about 110 ha [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]; It was likely a vast pasture rather than a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Bindon_Hill]"}]'::jsonb),
    ('eb9e5db8-a757-4451-8af7-b5eb273a5c9d'::uuid, 'card_description', '2nd millennium BC. Bronze Age rectangular tombs at Nakhchivan, covered in stone slabs 1 m long, oriented north to south. Excavations found pottery, bronze ornaments, and the bones of the interred.', 'At the Nakhchivan Necropolises, farm work in 1968 destroyed earth graves and revealed Bronze Age rectangular tombs covered with stone slabs 1 m long, their skeletons very poorly preserved.', 'teaser-card-s006:eb9e5db8-a757-4451-8af7-b5eb273a5c9d:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'cc0946e3eeba6cf80211a1936057df3062b113b4f1a08cafa312bad47ee2da52|2e0d34ed8f22ff6329b730be41aa50cedcbc019d1059285cf27c4d1eef28fc50|2e0d34ed8f22ff6329b730be41aa50cedcbc019d1059285cf27c4d1eef28fc50', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At the Nakhchivan Necropolises, farm work in 1968 destroyed earth graves and revealed Bronze Age rectangular tombs covered with stone slabs 1 m long, their skeletons very poorly preserved."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "farm work destroyed earth graves [S2]; this happened in 1968 [S2]; the farm work led to the site''s discovery [S2]; the site dates to the Bronze Age [S1]; the tombs are rectangular [S3]; the tombs are covered with stone slabs [S3]; the slabs are 1 m long [S3]; the skeletons are very poorly preserved [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Nakhchivan necropolis is a Bronze Age burial ground (necropolis) at the city of Nakhchivan, Azerbaijan [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; The site was revealed in 1968 [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; Farm work destroyed earth graves [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; The tombs date to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; The tombs are rectangular [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; The tombs are covered with stone slabs [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; The stone slabs are 1 m long [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]; The skeletons are very poorly preserved [SUPPORTED: https://en.wikipedia.org/wiki/Nakhchivan_necropolises]"}]'::jsonb),
    ('ec7f3fd8-9328-4a69-bf84-594f4fc2aa2a'::uuid, 'card_description', 'A Roman auxiliary fort guarding a bend of the River Noe from the 1st to 4th century AD. A civilian settlement grew up around it, as happened at forts across Britannia.', 'Above a tight bend of the River Noe, Navio Roman Fort guarded the Doctor''s Gate route. Excavations in 1903 uncovered steps down to an underground stone-walled chamber below its headquarters.', 'teaser-card-s006:ec7f3fd8-9328-4a69-bf84-594f4fc2aa2a:card_description', 'teaser-card-s006 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '854419491b9ddf75c348bf7542de9572fd8b9414a9e2ec65cf2b85e90048561d|c29b89ab9922e1fd64c0b2cb63d73ad6b07f0a9fe4a6d13eb9f4b3070917f101|c29b89ab9922e1fd64c0b2cb63d73ad6b07f0a9fe4a6d13eb9f4b3070917f101', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Above a tight bend of the River Noe, Navio Roman Fort guarded the Doctor''s Gate route. Excavations in 1903 uncovered steps down to an underground stone-walled chamber below its headquarters."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the fort stands above a tight bend of the River Noe [S1]; it guarded the Doctor''s Gate route [S7]; excavations in 1903 uncovered steps down to an underground stone-walled chamber [S6]; the chamber lies below the headquarters building [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Navio is a Roman fort in England [SUPPORTED: https://en.wikipedia.org/wiki/Navio_Roman_Fort]; The fort stands above a tight bend of the River Noe [SUPPORTED: https://en.wikipedia.org/wiki/Navio_Roman_Fort]; The fort guarded the Doctor''s Gate route [SUPPORTED: https://en.wikipedia.org/wiki/Navio_Roman_Fort]; Excavations took place in 1903 [SUPPORTED: https://en.wikipedia.org/wiki/Navio_Roman_Fort]; The 1903 excavations uncovered steps down to an underground stone-walled chamber [SUPPORTED: https://en.wikipedia.org/wiki/Navio_Roman_Fort]; The chamber lies below the fort''s headquarters building [SUPPORTED: https://en.wikipedia.org/wiki/Navio_Roman_Fort]"}]'::jsonb),
    ('ec9daf3f-c6a6-4ada-8234-c667393b0e1e'::uuid, 'card_description', 'A 2nd-century AD Roman spa settlement near ancient Pergamon. Its therapeutic hot springs drew visitors for centuries — an ancient health resort.', 'Mentioned only once, by Aelius Aristides in the 2nd century, the ancient spa of Allianoi is a very recent discovery: thermal baths, bridges, streets and a nympheum near Bergama.', 'teaser-card-s006:ec9daf3f-c6a6-4ada-8234-c667393b0e1e:card_description', 'teaser-card-s006 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '3bfa051dd86a1b1c7a16628f15b6c3ef4e06ddafa6ed94cd254ab6cb7b93fcdc|39819d9a9a2c745f25fc30c7bf69a4a4f1c1b3587c232d97dd9e65c2117bf488|39819d9a9a2c745f25fc30c7bf69a4a4f1c1b3587c232d97dd9e65c2117bf488', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mentioned only once, by Aelius Aristides in the 2nd century, the ancient spa of Allianoi is a very recent discovery: thermal baths, bridges, streets and a nympheum near Bergama."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Allianoi was mentioned only once [S4]; the mention was by Aelius Aristides in the 2nd century [S4]; it is an ancient spa [S1]; it is a very recent discovery [S3]; it has thermal baths, bridges, streets and a nympheum [S6]; it lies near Bergama [S1, S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Allianoi is an ancient spa settlement near Bergama, Turkey [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; Allianoi is mentioned only once in ancient sources [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; The single mention is by Aelius Aristides [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; The mention dates to the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; Allianoi is a very recent discovery [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; The site has thermal baths [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; The site has bridges [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; The site has streets [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]; The site has a nympheum [SUPPORTED: https://en.wikipedia.org/wiki/Allianoi]"}]'::jsonb),
    ('ed78d548-5409-4909-abc0-793390dfed1c'::uuid, 'card_description', 'The Valley of the Kings garnered significant attention following the discovery of the tomb of Tutankhamun in 1922.', 'In a wadi on the Nile''s west bank, opposite Thebes, the Valley of the Kings is known to contain 65 tombs and chambers, the royal ones decorated with scenes from Egyptian mythology.', 'teaser-card-s006:ed78d548-5409-4909-abc0-793390dfed1c:card_description', 'teaser-card-s006 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f520da77df7d3136754ada527128e611646a7e3fa28753b1cd59e32c503d4426|e6968a0fb49cd475e47eb33fec0ba275628d4292d0819111394039ee7eee9f16|e6968a0fb49cd475e47eb33fec0ba275628d4292d0819111394039ee7eee9f16', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In a wadi on the Nile''s west bank, opposite Thebes, the Valley of the Kings is known to contain 65 tombs and chambers, the royal ones decorated with scenes from Egyptian mythology."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it lies in a wadi [S2]; on the west bank of the Nile [S2]; opposite Thebes [S2]; it is known to contain 65 tombs and chambers [S3]; the royal tombs are decorated with scenes from Egyptian mythology [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Valley of the Kings is a burial valley of rock-cut tombs on the Nile''s west bank opposite Thebes, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Kings]; The valley is a wadi [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Kings]; It lies on the west bank of the Nile [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Kings]; It lies opposite Thebes [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Kings]; The valley is known to contain 65 tombs and chambers [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Kings]; The royal tombs are decorated with scenes from Egyptian mythology [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Kings]"}]'::jsonb),
    ('ed8ffc34-ab81-4b4d-b852-ae20205fb2b5'::uuid, 'card_description', 'A cave with Neanderthal remains from the Mousterian period. Marine shell pigments and ornaments found here rewrote assumptions about Neanderthal cognition.', 'Near Xàtiva, Neanderthals came to Cova Negra only for short stays. Of 247 remains of 18 bird species found there, a substantial part displays evidence of human manipulation and consumption.', 'teaser-card-s006:ed8ffc34-ab81-4b4d-b852-ae20205fb2b5:card_description', 'teaser-card-s006 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '0369d67acca270dfcfd04be5785e337bf8ad5a8a1df5237c501bcc5b04a1271b|d439e7340cd11de0dceef8513c849e234fdc23d3e49d74fc2eee970f79ea6da1|d439e7340cd11de0dceef8513c849e234fdc23d3e49d74fc2eee970f79ea6da1', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near Xàtiva, Neanderthals came to Cova Negra only for short stays. Of 247 remains of 18 bird species found there, a substantial part displays evidence of human manipulation and consumption."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cova Negra is near Xàtiva [S1]; Neanderthals occupied Cova Negra [S1]; their occupation was sporadic and short-term [S1]; 247 bird remains were found there [S2]; the remains belong to 18 bird species [S2]; a substantial part of the analysed remains shows evidence of human manipulation and consumption [S2, W1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cova Negra is a site visited by Neanderthals [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Negra]; Cova Negra lies near Xàtiva [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Negra]; Neanderthals came to Cova Negra only for short stays [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Negra]; 247 bird remains were found at Cova Negra [SUPPORTED: https://digitalcommons.usf.edu/kip_articles/641/]; The bird remains belong to 18 species [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Negra]; A substantial part of the bird remains displays evidence of human manipulation [SUPPORTED: https://digitalcommons.usf.edu/kip_articles/641/]; The bird remains show evidence of consumption by humans (Neanderthals) [SUPPORTED: https://digitalcommons.usf.edu/kip_articles/641/]"}, {"source": "web fact W1", "url": "https://digitalcommons.usf.edu/kip_articles/641/", "quote": "A substantial part of the remains analyzed displays human manipulation and consumption evidence"}]'::jsonb),
    ('ee29e9ee-2892-4487-b318-0c0fc88f9a25'::uuid, 'card_description', 'The only purpose-built brothel identified in Pompeii, frozen by Vesuvius in 79 AD. Erotic frescoes above each doorway served as a menu of services for visiting clients.', 'About two blocks east of the forum, near the Stabian Baths, the Lupanar of Pompeii keeps erotic paintings on its walls: a Roman brothel that was also a place of leisure for local men.', 'teaser-card-s006:ee29e9ee-2892-4487-b318-0c0fc88f9a25:card_description', 'teaser-card-s006 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '2644c2cab6d0e7d04dbfee77ce025eb2359fe4c34bfe8edf00c2e41f39154f1a|f3bad9110824e41992ece5691b70989250ecfceb936a0ca51180be290252face|f3bad9110824e41992ece5691b70989250ecfceb936a0ca51180be290252face', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "About two blocks east of the forum, near the Stabian Baths, the Lupanar of Pompeii keeps erotic paintings on its walls: a Roman brothel that was also a place of leisure for local men."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it lies about two blocks east of the forum [S3]; it is near the Stabian Baths [S3]; it has erotic paintings on its walls [S2]; it was a Roman brothel [S1]; it was also a place of leisure for local men [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Lupanar of Pompeii is (the ruin of) an ancient Roman brothel in the city of Pompeii [SUPPORTED: https://en.wikipedia.org/wiki/Lupanar_(Pompeii)]; It lies about two blocks east of the forum [SUPPORTED: https://en.wikipedia.org/wiki/Lupanar_(Pompeii)]; It lies near the Stabian Baths [SUPPORTED: https://en.wikipedia.org/wiki/Lupanar_(Pompeii)]; It keeps erotic paintings on its walls [SUPPORTED: https://en.wikipedia.org/wiki/Lupanar_(Pompeii)]; The brothel was also a place of leisure for local men [SUPPORTED: https://en.wikipedia.org/wiki/Lupanar_(Pompeii)]"}]'::jsonb),
    ('ee3d64b9-9207-4bff-8b91-3007ee811ecb'::uuid, 'card_description', NULL, 'Beaumont Cut, a canal opened in 1832 to link a quay with Hamford Water and the North Sea, still holds water. The first canal on the site may have been Roman, perhaps for salt extraction.', 'teaser-card-s006:ee3d64b9-9207-4bff-8b91-3007ee811ecb:card_description', 'teaser-card-s006 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '1553d895f9a27b7b3c6976f310231e6784d68f3539bdde0668386b1b6a4d1810|66f7a2b733dd521627562c87dd75c03f2c4e77296828779a5d4b02fbb0f39aad|66f7a2b733dd521627562c87dd75c03f2c4e77296828779a5d4b02fbb0f39aad', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Beaumont Cut, a canal opened in 1832 to link a quay with Hamford Water and the North Sea, still holds water. The first canal on the site may have been Roman, perhaps for salt extraction."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Beaumont Cut is a canal [S1]; it opened in 1832 [S2]; it linked a quay with Hamford Water and the North Sea [S1]; its line still holds water [S6]; the first canal on the site may have been Roman (hedged) [S3]; perhaps built for salt extraction (hedged) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Beaumont Cut is a canal in Essex, England [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]; The canal links a quay (Beaumont Quay) with Hamford Water [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]; Through Hamford Water the canal links the quay with the North Sea [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]; The canal was opened in 1832 [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]; The canal still holds water [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]; The first canal on the site may have been Roman [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]; The Roman canal was perhaps connected with salt extraction [SUPPORTED: https://en.wikipedia.org/wiki/Beaumont_Cut]"}]'::jsonb),
    ('ee67e46b-e0ee-4bbe-b7bb-49000bdc5e94'::uuid, 'card_description', 'Constructed in the 1st century AD, this theatre could once seat 15,000 people and was used also as an amphitheatre to show gladiatorial combats.', 'Under the lower terraces of the Arènes de Lutèce, some small rooms appear to have been animal cages opening into the arena. Once able to seat 15,000, it was filled in, its location lost.', 'teaser-card-s006:ee67e46b-e0ee-4bbe-b7bb-49000bdc5e94:card_description', 'teaser-card-s006 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '9ad062c382b14aff619423019fab00803841b817afa1d9514ac185d9fe01e034|91e31b365e8a6dd7c9c2e2d6dd7f5188e009bbf14ce3768c9b6337839cbba47d|91e31b365e8a6dd7c9c2e2d6dd7f5188e009bbf14ce3768c9b6337839cbba47d', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Under the lower terraces of the Arènes de Lutèce, some small rooms appear to have been animal cages opening into the arena. Once able to seat 15,000, it was filled in, its location lost."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "there were small rooms under the lower terraces [S3]; some of them appear to have been animal cages (hedged) [S3]; the cages opened into the arena [S3]; it could once seat 15,000 [S2]; it was filled in [S5]; its location was lost [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Arènes de Lutèce is an ancient Roman arena (amphitheatre-theatre) in Paris [SUPPORTED: https://fr.wikipedia.org/wiki/Ar%C3%A8nes_de_Lut%C3%A8ce]; Small rooms lie under its lower terraces [SUPPORTED: https://en.wikipedia.org/wiki/Ar%C3%A8nes_de_Lut%C3%A8ce]; Some of these rooms appear to have been animal cages opening into the arena [SUPPORTED: https://en.wikipedia.org/wiki/Ar%C3%A8nes_de_Lut%C3%A8ce]; It could once seat 15,000 people [SUPPORTED: https://en.wikipedia.org/wiki/Ar%C3%A8nes_de_Lut%C3%A8ce]; It was filled in [SUPPORTED: https://en.wikipedia.org/wiki/Ar%C3%A8nes_de_Lut%C3%A8ce]; Its location was lost [SUPPORTED: https://en.wikipedia.org/wiki/Ar%C3%A8nes_de_Lut%C3%A8ce]"}]'::jsonb),
    ('f03f19b4-c5aa-41b9-a874-fa37fff2ead7'::uuid, 'card_description', 'Starting in 1895, Friedrich Hiller von Gaertringen systematically investigated the city until 1904.', 'High on the limestone hill of Mesa Vouno on Santorini, Ancient Thera kept inscriptions from its beginnings that are among the oldest known examples of the use of the Greek alphabet.', 'teaser-card-s006:f03f19b4-c5aa-41b9-a874-fa37fff2ead7:card_description', 'teaser-card-s006 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '55c7557bf28c687659a993ed894147e2bf1737f3258c7ee107c436a7821e76fe|757594fafcb110e296d0927bacb093db1e0df70803acdb8fa13784622d81097c|757594fafcb110e296d0927bacb093db1e0df70803acdb8fa13784622d81097c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "High on the limestone hill of Mesa Vouno on Santorini, Ancient Thera kept inscriptions from its beginnings that are among the oldest known examples of the use of the Greek alphabet."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it sits on top of the limestone hill of Mesa Vouno [S1]; it is on Santorini [S1]; inscriptions from the city''s beginnings were found there [S7]; those inscriptions are among the oldest known examples of the use of the Greek alphabet [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Ancient Thera is an ancient city (archaeological site) on Santorini [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Thera]; It lies high on the limestone hill of Mesa Vouno [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Thera]; Inscriptions from the city''s beginnings were found (survive) there [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Thera]; These inscriptions are among the oldest known examples of the use of the Greek alphabet [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Thera]"}]'::jsonb),
    ('f0b20fa9-aab2-400d-bfa8-24af297bb993'::uuid, 'card_description', 'Kastros lies at the north-easternmost tip of the Karpas Peninsula, about 4 km north of Apostolos Andreas Monastery.', 'On a little plateau on the steep flank of a limestone promontory, in a very inaccessible spot, Kastros held small round houses with hearths and the carbonised remains of einkorn and emmer.', 'teaser-card-s006:f0b20fa9-aab2-400d-bfa8-24af297bb993:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '1be77a99ce38662ac2621d1d13fdb639cee0e8f00a0f702dcd15e927168e083d|e4b37a3d1d3fcd53290ea098cb02fa0b4200e602b76b4ac4bbf94e53403adec6|e4b37a3d1d3fcd53290ea098cb02fa0b4200e602b76b4ac4bbf94e53403adec6', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a little plateau on the steep flank of a limestone promontory, in a very inaccessible spot, Kastros held small round houses with hearths and the carbonised remains of einkorn and emmer."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it lies on a little plateau on the steep flank of a limestone promontory [S3]; the spot is very inaccessible [S3]; the settlement had small round houses [S5]; the houses had hearths [S6]; carbonised remains of einkorn and emmer were found [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Kastros is a settlement (a place with houses) in Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Kastros]; It lies on a little plateau on the steep flank of a limestone promontory [SUPPORTED: https://en.wikipedia.org/wiki/Kastros]; The 