    ('f151db5d-5515-495e-ba5e-bde2a46c553a'::uuid, 'card_description', 'Buckton Roman Fort is an archaeological site at Buckton, about 1 mile south-west of Leintwardine. Originally there were turf ramparts and timber gate towers, constructed about AD 80.', 'Entirely buried, Buckton Roman Fort was spotted from the air in a drought in 1959. Above the River Teme''s floodplain, it first had turf ramparts and timber gate towers, built about AD 80.', 'teaser-card-s006:f151db5d-5515-495e-ba5e-bde2a46c553a:card_description', 'teaser-card-s006 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '2421e90bba0b67f735341acde70516e763f001d7780656ad417d368190694e09|f83d6c39ab81d8ba4c89b370bc0182a0e1254367fc092d0327d852e191176a8f|f83d6c39ab81d8ba4c89b370bc0182a0e1254367fc092d0327d852e191176a8f', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Entirely buried, Buckton Roman Fort was spotted from the air in a drought in 1959. Above the River Teme''s floodplain, it first had turf ramparts and timber gate towers, built about AD 80."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the remains are entirely buried [S3]; the fort was spotted from the air [S3]; this was during a drought in 1959 [S3]; it lies above the floodplain of the River Teme [S2]; it originally had turf ramparts and timber gate towers [S5]; these were built about AD 80 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Buckton Roman Fort is a Roman fort at Buckton in England (Herefordshire) [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; The fort''s remains are entirely buried [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; It was spotted from the air [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; It was spotted during a drought [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; It was spotted in 1959 [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; The fort lies above the floodplain of the River Teme [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; The fort first had turf ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; The fort first had timber gate towers [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]; The first fort was built about AD 80 [SUPPORTED: https://en.wikipedia.org/wiki/Buckton_Roman_Fort]"}]'::jsonb),
    ('f24eeac5-51df-4456-bcee-607d7deacdef'::uuid, 'card_description', 'Mitanni palace city on the Tigris built around 1600 BC, destroyed by earthquake c. 1350 BC. Kemune was rediscovered in 2013 only when drought dropped the Mosul Dam reservoir, exposing its walls.', 'When a severe drought lowered the Mosul Dam reservoir, Kemune emerged again: a Mitanni-era city destroyed by an earthquake around 1350 BC, where about 100 cuneiform tablets were recovered.', 'teaser-card-s006:f24eeac5-51df-4456-bcee-607d7deacdef:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7605b1c967c4e58c8fede72f9458540aa892e018a862db4b00731f1c04356dd4|cc0f6459d6a94a4a3219244d9ba0ca1e2e5e9a53a353349a4380a120eea3b695|cc0f6459d6a94a4a3219244d9ba0ca1e2e5e9a53a353349a4380a120eea3b695', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "When a severe drought lowered the Mosul Dam reservoir, Kemune emerged again: a Mitanni-era city destroyed by an earthquake around 1350 BC, where about 100 cuneiform tablets were recovered."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "a severe drought lowered the reservoir [S6]; the reservoir is that of the Mosul Dam [S1]; Kemune emerged again [S6]; it was a Mitanni-era city [S2]; it was destroyed by an earthquake around 1350 BC [S2]; about 100 cuneiform tablets were recovered there [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Kemune is an archaeological site (an ancient city) in the Mosul Dam reservoir in Iraq [SUPPORTED: https://en.wikipedia.org/wiki/Kemune]; A severe drought lowered the water of the Mosul Dam reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Kemune]; Kemune emerged again from the reservoir (it had been exposed before) [SUPPORTED: https://en.wikipedia.org/wiki/Kemune]; Kemune was a city of the Mitanni era [SUPPORTED: https://www.pr.uni-freiburg.de/pm-en/press-releases-2022/a-3400-year-old-city-emerges-from-the-tigris-river]; The city was destroyed by an earthquake [SUPPORTED: https://www.pr.uni-freiburg.de/pm-en/press-releases-2022/a-3400-year-old-city-emerges-from-the-tigris-river]; The earthquake struck around 1350 BC [SUPPORTED: https://en.wikipedia.org/wiki/Kemune]; About 100 cuneiform tablets were recovered at Kemune [SUPPORTED: https://en.wikipedia.org/wiki/Kemune]"}]'::jsonb),
    ('f294fd21-7428-4c73-9810-dae8ff8ee546'::uuid, 'card_description', 'Eyice notes that the percentage of standing buildings is higher in Karakabaklı than in most other ancient settlements.', 'At Karakabaklı, notes Semavi Eyice, a higher share of buildings stands than in most other ancient settlements: houses, basilicas, a tetrapylon, cisterns and a partly unearthed Roman road.', 'teaser-card-s006:f294fd21-7428-4c73-9810-dae8ff8ee546:card_description', 'teaser-card-s006 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '871de828c57d169fbc45f914719d1118ec6eb50f047eacb0af870bea09b65fc0|1c058e93602328916021ffb951220530109bcd5c78f12a851c95af154cb2456e|1c058e93602328916021ffb951220530109bcd5c78f12a851c95af154cb2456e', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At Karakabaklı, notes Semavi Eyice, a higher share of buildings stands than in most other ancient settlements: houses, basilicas, a tetrapylon, cisterns and a partly unearthed Roman road."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Semavi Eyice notes the share of standing buildings is higher than in most other ancient settlements [S6]; there are houses [S5]; there are basilicas, a tetrapylon and cisterns [S8]; there is a partly unearthed Roman road [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Karakabaklı is an ancient settlement (archaeological site) in Türkiye [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; Karakabaklı is an ancient settlement [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; Semavi Eyice notes that a higher share of buildings stands at Karakabaklı than in most other ancient settlements [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; The site has houses [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; The site has basilicas [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; The site has a tetrapylon [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; The site has cisterns [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]; The site has a partly unearthed Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Karakabakl%C4%B1]"}]'::jsonb),
    ('f3c604c5-20b7-4ae6-bb53-728404203d7a'::uuid, 'card_description', 'The artifacts collected, as well as more recent radiocarbon dating, suggest that the chamber was used in the Late Neolithic period between the middle and end of the 4th millennium BC.', 'Seven vertical stones are believed to have formed the polygonal chamber of the Anta de Agualva, a dolmen now in an urban area of Sintra, likely used in the Late Neolithic period.', 'teaser-card-s006:f3c604c5-20b7-4ae6-bb53-728404203d7a:card_description', 'teaser-card-s006 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '2fac721f62235beaa444465b530ec0a10123d375dc1f38b51636ef2a0e707c9d|579db1db39bed7ba9ba79156747f6d0c9ee04040c88df23e345f4b2283e2866b|579db1db39bed7ba9ba79156747f6d0c9ee04040c88df23e345f4b2283e2866b', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Seven vertical stones are believed to have formed the polygonal chamber of the Anta de Agualva, a dolmen now in an urban area of Sintra, likely used in the Late Neolithic period."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "seven vertical stones are believed to have formed the chamber (hedged) [S2]; the chamber is polygonal [S2]; it is a dolmen [S1]; it is now in an urban area in the municipality of Sintra [S1]; it was likely used in the Late Neolithic period (hedged) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Anta de Agualva is a dolmen in Sintra, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Anta_de_Agualva]; The dolmen now stands in an urban area [SUPPORTED: https://en.wikipedia.org/wiki/Anta_de_Agualva]; The dolmen is believed to have had a polygonal chamber [SUPPORTED: https://en.wikipedia.org/wiki/Anta_de_Agualva]; Seven vertical stones are believed to have formed the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Anta_de_Agualva]; The dolmen was likely used in the Late Neolithic period [SUPPORTED: https://en.wikipedia.org/wiki/Anta_de_Agualva]"}]'::jsonb),
    ('f48403a7-03b2-4d2b-ad9f-1d8369a502c8'::uuid, 'card_description', 'Capital of the Postclassic Mam kingdom before being conquered by the K''iche''. Its temple-pyramids show a mix of Mam and K''iche'' architectural styles.', 'Temple-pyramids with double stairways rise around large plazas at Parque Arqueológico Zaculeu, once the walled capital of the Mam kingdom, besieged by Spanish conquistadors in AD 1525.', 'teaser-card-s006:f48403a7-03b2-4d2b-ad9f-1d8369a502c8:card_description', 'teaser-card-s006 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'fb7fc49d0969ff1d1d06a55058e374a28b3018b2010ba3e75baf98dbca3f9392|9c6e2761403331d9923f0b9bd913a3692b6338a22ce0bd2584c7d42317db2a87|9c6e2761403331d9923f0b9bd913a3692b6338a22ce0bd2584c7d42317db2a87', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Temple-pyramids with double stairways rise around large plazas at Parque Arqueológico Zaculeu, once the walled capital of the Mam kingdom, besieged by Spanish conquistadors in AD 1525."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site has temple-pyramids with double stairways [S6]; the pyramids rise around large plazas [S7]; it was once the capital of the Mam kingdom [S3]; it was walled (fortified with walls) [S8]; it was besieged by Spanish conquistadors [S5]; the siege was in AD 1525 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Parque Arqueológico Zaculeu is a pre-Columbian Maya archaeological site (ancient city) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; The site has temple-pyramids [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; The temple-pyramids have double stairways [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; The pyramids rise around large plazas [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; Zaculeu was once the capital of the Mam kingdom [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; The capital was walled [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; Zaculeu was besieged by Spanish conquistadors [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]; The siege took place in AD 1525 [SUPPORTED: https://en.wikipedia.org/wiki/Zaculeu]"}]'::jsonb),
    ('f57509f6-ee97-464e-8b8c-0393db104d05'::uuid, 'card_description', 'A Roman city from 50 AD that became the capital of Pannonia Inferior. A working Roman water organ, one of only a few ever found, was discovered here.', 'In Budapest''s Óbuda district lie the ruins of Aquincum, a Roman border city where a legion of 6,000 men was stationed by AD 89 and where two amphitheatres stood, one civil, one military.', 'teaser-card-s006:f57509f6-ee97-464e-8b8c-0393db104d05:card_description', 'teaser-card-s006 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '8474dd5fbde637e2ad228fa72f3981fd3428628e6209147cf5f6e9fedfebb0b9|737c86091bab627f7d10d7c649f12ef0ec919e9e7dfb5e369527ae28ad095a38|737c86091bab627f7d10d7c649f12ef0ec919e9e7dfb5e369527ae28ad095a38', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In Budapest''s Óbuda district lie the ruins of Aquincum, a Roman border city where a legion of 6,000 men was stationed by AD 89 and where two amphitheatres stood, one civil, one military."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the ruins lie in the Óbuda district of Budapest [S2]; Aquincum was a Roman city on the border [S1, S4]; a legion of 6,000 men was stationed there [S5]; the legion was stationed there by AD 89 [S5]; two amphitheatres stood there [S8]; one amphitheatre was civil, one military [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Aquincum is the ruins of an ancient Roman city [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]; The ruins lie in Budapest''s Óbuda district [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]; Aquincum was a Roman border (frontier) city [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]; A legion of 6,000 men was stationed there [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]; The legion was stationed there by AD 89 [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]; Two amphitheatres stood at Aquincum [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]; One amphitheatre was civil and one military [SUPPORTED: https://en.wikipedia.org/wiki/Aquincum]"}]'::jsonb),
    ('f784a924-a2de-42ae-b530-4b292753fa8f'::uuid, 'card_description', 'The start of the Ridgeway, one of Britain''s oldest roads, likely in use since the Stone Age. Several scheduled barrows and ancient monuments cluster around this hill.', 'Overton Hill, part of the Stonehenge and Avebury World Heritage Site, rises 571 ft at the southern edge of the Marlborough Downs. From here the Ridgeway sets out along an ancient trackway.', 'teaser-card-s006:f784a924-a2de-42ae-b530-4b292753fa8f:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '34a104b29da6d506ddc1165b6d51d4a8aed967c71980f505d92e412e091ee4d9|48e79e8f8e9fab3b371ced108289824dde83d16cc263a0883faa5a6832439ad5|48e79e8f8e9fab3b371ced108289824dde83d16cc263a0883faa5a6832439ad5', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Overton Hill, part of the Stonehenge and Avebury World Heritage Site, rises 571 ft at the southern edge of the Marlborough Downs. From here the Ridgeway sets out along an ancient trackway."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Overton Hill is part of the Stonehenge and Avebury World Heritage Site [S4]; the hill rises 571 ft [S1]; it is at the southern edge of the Marlborough Downs [S1]; the Ridgeway starts here [S3]; the Ridgeway follows an ancient trackway [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Overton Hill is a hill in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Overton_Hill]; Overton Hill is part of the Stonehenge and Avebury World Heritage Site [SUPPORTED: https://en.wikipedia.org/wiki/Overton_Hill]; Overton Hill rises 571 ft [SUPPORTED: https://en.wikipedia.org/wiki/Overton_Hill]; Overton Hill lies at the southern edge of the Marlborough Downs [SUPPORTED: https://en.wikipedia.org/wiki/Overton_Hill]; The Ridgeway sets out from Overton Hill [SUPPORTED: https://en.wikipedia.org/wiki/Overton_Hill]; The Ridgeway runs along an ancient trackway [SUPPORTED: https://en.wikipedia.org/wiki/Overton_Hill]"}]'::jsonb),
    ('f7c6b78b-4d82-4443-bd30-ecda84f4bc6e'::uuid, 'card_description', 'An archaeological layer cake: Iron Age broch, Pictish buildings, Viking remains, and Medieval structures, each generation building atop the last for thousands of years.', 'In 1975, a new road for Sumburgh Airport cut into a grassy mound and exposed a broch wall: Old Scatness, where Iron Age, Pictish, Viking and medieval generations each built anew.', 'teaser-card-s006:f7c6b78b-4d82-4443-bd30-ecda84f4bc6e:card_description', 'teaser-card-s006 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '4bbf6248cbab2f415e59842079c08cd5267c6c3992c3cdd4ccdf2a33c51a7acd|ce1cb73d74065b2a5288b183d663992ed505cf67704539056623f665de649332|ce1cb73d74065b2a5288b183d663992ed505cf67704539056623f665de649332', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In 1975, a new road for Sumburgh Airport cut into a grassy mound and exposed a broch wall: Old Scatness, where Iron Age, Pictish, Viking and medieval generations each built anew."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the discovery happened in 1975 [W1]; a new road was being built [S4, W1]; the road was part of the Sumburgh Airport improvements [S4]; the road works exposed part of a broch wall [S4]; the broch wall lay in a grassy mound [S4]; the site has Iron Age, Pictish, Viking and medieval remains [S2]; each new generation added buildings [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Old Scatness is an Iron Age broch and settlement site in Shetland, Scotland, near Sumburgh Airport [SUPPORTED: https://www.shetland.org/visit/areas/south-mainland/old-scatness-broch-and-iron-age-village]; The site was discovered in 1975 [SUPPORTED: https://www.shetlandamenity.org/old-scatness]; It was discovered when a new road for Sumburgh Airport was built [SUPPORTED: https://www.shetland.org/visit/areas/south-mainland/old-scatness-broch-and-iron-age-village]; The road cut into a grassy mound [SUPPORTED: https://en.wikipedia.org/wiki/Old_Scatness]; The road exposed a broch wall [SUPPORTED: https://en.wikipedia.org/wiki/Old_Scatness]; Iron Age people built at Old Scatness [SUPPORTED: https://en.wikipedia.org/wiki/Old_Scatness]; Pictish people built at Old Scatness [SUPPORTED: https://www.shetland.org/visit/areas/south-mainland/old-scatness-broch-and-iron-age-village]; Vikings built at Old Scatness [SUPPORTED: https://en.wikipedia.org/wiki/Old_Scatness]; Medieval people built at Old Scatness [SUPPORTED: https://en.wikipedia.org/wiki/Old_Scatness]; Each generation built anew on the site [SUPPORTED: https://en.wikipedia.org/wiki/Old_Scatness]"}, {"source": "web fact W1", "url": "https://www.research.ed.ac.uk/en/publications/brochs-and-beyond-excavations-at-old-scatness-shetland/", "quote": "Completely unknown until 1975, when it was revealed during the construction of a new road"}]'::jsonb),
    ('f7f6d178-0de5-4cc8-a1f7-d473bb13e06c'::uuid, 'card_description', 'Natural rock fissures used as shrines to Zeus, Apollo, Pan, Aphrodite, and Eros. Multiple gods worshipped in caves beneath one of the world''s most famous hills.', 'Natural fissures in the rock were the Cave Sanctuaries of the Acropolis of Athens: three caves for Pan, Zeus and Apollo, and on the east slope the Aglaureion, 14m across the mouth.', 'teaser-card-s006:f7f6d178-0de5-4cc8-a1f7-d473bb13e06c:card_description', 'teaser-card-s006 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '76b81ba1a57e7e406c5837aadd1cb9c04dc59cc6aec180283b297bd9687f8267|c88b1ad7439e87b4ff7e47c228f960d8de2346dc109416fa7908a7c82307bc14|c88b1ad7439e87b4ff7e47c228f960d8de2346dc109416fa7908a7c82307bc14', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Natural fissures in the rock were the Cave Sanctuaries of the Acropolis of Athens: three caves for Pan, Zeus and Apollo, and on the east slope the Aglaureion, 14m across the mouth."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Cave Sanctuaries are natural fissures in the rock of the Acropolis [S1]; three caves were dedicated to Pan, Zeus and Apollo [S2]; the Aglaureion is on the east slope [S3]; the Aglaureion is 14m across the mouth [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Cave Sanctuaries of the Acropolis of Athens were natural fissures in the rock of the Acropolis used as places of worship [SUPPORTED: https://en.wikipedia.org/wiki/Cave_Sanctuaries_of_the_Acropolis_of_Athens]; There are three caves (on the north-west slope) for Pan, Zeus and Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Cave_Sanctuaries_of_the_Acropolis_of_Athens]; One cave was for Pan [SUPPORTED: https://en.wikipedia.org/wiki/Cave_Sanctuaries_of_the_Acropolis_of_Athens]; One cave was for Zeus [SUPPORTED: https://en.wikipedia.org/wiki/Cave_Sanctuaries_of_the_Acropolis_of_Athens]; One cave was for Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Cave_Sanctuaries_of_the_Acropolis_of_Athens]; The Aglaureion lies on the east slope [SUPPORTED: https://en.wikipedia.org/wiki/Cave_Sanctuaries_of_the_Acropolis_of_Athens]; The Aglaureion is a cave 14 m across the mouth [SUPPORTED: http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=19819]"}]'::jsonb),
    ('f8263779-fd9f-4983-9561-3f7755417987'::uuid, 'card_description', 'Sarsen stones frame this 3300 BC Severn-Cotswold tomb in Wiltshire, built to hold communal burials and topped by a breast-shaped mound. An arrowhead found inside hints at more than funeral rites.', 'On a breast-shaped hill in Wiltshire lies Adam''s Grave, a Neolithic long barrow 70 metres long whose sarsen chamber held partial human skeletons. The Anglo-Saxons called it Woden''s Barrow.', 'teaser-card-s006:f8263779-fd9f-4983-9561-3f7755417987:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '262627c672fb10fc4cd347d7eda4b6bb071d75ba490281998974c54975387b11|1b048d14bde33e8ac4eab26c2f6425130fd9d514c474c38c548f2f2456a10075|1b048d14bde33e8ac4eab26c2f6425130fd9d514c474c38c548f2f2456a10075', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a breast-shaped hill in Wiltshire lies Adam''s Grave, a Neolithic long barrow 70 metres long whose sarsen chamber held partial human skeletons. The Anglo-Saxons called it Woden''s Barrow."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Adam''s Grave is on a breast-shaped hill [S6]; it is in Wiltshire [S1]; it is a Neolithic long barrow [S1]; the barrow is 70 metres long [S6]; its chamber was made of sarsen stones [S4]; the chamber contained partial human skeletons [S4]; in the Anglo-Saxon period it was known as Woden''s Barrow [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Adam''s Grave is a long barrow (a burial mound) in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Adam%27s_Grave]; The long barrow dates from the Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Battle_of_Woden%27s_Burg_(592)]; It lies on a breast-shaped hill [SUPPORTED: https://en.wikipedia.org/wiki/Adam%27s_Grave]; The long barrow is 70 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Adam%27s_Grave]; Its chamber is built of sarsen stones [SUPPORTED: https://en.wikipedia.org/wiki/Adam%27s_Grave]; The chamber held partial human skeletons [SUPPORTED: https://en.wikipedia.org/wiki/Adam%27s_Grave]; The Anglo-Saxons called it Woden''s Barrow [SUPPORTED: https://en.wikipedia.org/wiki/Battle_of_Woden%27s_Burg_(592)]"}]'::jsonb),
    ('f8beb699-0b16-4b18-b322-bdf7ca612ac9'::uuid, 'card_description', 'A Roman villa whose Orpheus mosaic is the second largest in Europe, dating to ~325 AD. The mosaic is now buried under a churchyard, only uncovered for rare public viewings.', 'Nothing of Woodchester Roman Villa is visible above ground, yet its Orpheus mosaic, the second largest of its kind in Europe, shows Orpheus charming all forms of life with his lyre.', 'teaser-card-s006:f8beb699-0b16-4b18-b322-bdf7ca612ac9:card_description', 'teaser-card-s006 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '470ac7fc9367cafb4446043cbca6ce404c843df553da2b56141b59281947a202|9e6d723a2629eac69605daa8ba2e9356a85dd04269096d75c83881f6847f0ae5|9e6d723a2629eac69605daa8ba2e9356a85dd04269096d75c83881f6847f0ae5', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Nothing of Woodchester Roman Villa is visible above ground, yet its Orpheus mosaic, the second largest of its kind in Europe, shows Orpheus charming all forms of life with his lyre."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "nothing of the villa is visible above ground [S3]; the villa has an Orpheus mosaic [S4]; the mosaic is the second largest of its kind in Europe [S4]; the mosaic depicts Orpheus charming all forms of life with his lyre [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Woodchester Roman Villa is a Roman villa site (at Woodchester, Gloucestershire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Woodchester_Roman_Villa]; Nothing of the villa is visible above ground [SUPPORTED: https://en.wikipedia.org/wiki/Woodchester_Roman_Villa]; The villa has an Orpheus mosaic [SUPPORTED: https://en.wikipedia.org/wiki/Woodchester_Roman_Villa]; The Orpheus mosaic is the second largest of its kind in Europe [SUPPORTED: https://coriniummuseum.org/2025/09/orpheus-mosaics-what-are-their-significance-and-differences/]; The mosaic shows Orpheus charming all forms of life with his lyre [SUPPORTED: https://en.wikipedia.org/wiki/Woodchester_Roman_Villa]"}]'::jsonb),
    ('faab0d7b-1f66-45b9-8b1b-95697a3fc320'::uuid, 'card_description', 'Pre-Hispanic site at 3,781 m in the Huancavelica highlands, with an ancient town, a stone forest, and caves with rock paintings. A rare combination of settlement and cave art at high altitude.', 'At 3,781 metres in the Huancavelica Region lies Wiraqucha Pirqa, Quechua for wall of Viracocha: a little pre-Hispanic town and a stone forest whose caves hold cave paintings.', 'teaser-card-s006:faab0d7b-1f66-45b9-8b1b-95697a3fc320:card_description', 'teaser-card-s006 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'ff0a4a98e83fe00fb9435e4b2d3a395cff3126c7357f1b982098e92ccc11db8c|38ecb47ab036b49d9ffaa44036952dcedfd533b0b81f0cee7c805a766d8a5ea3|38ecb47ab036b49d9ffaa44036952dcedfd533b0b81f0cee7c805a766d8a5ea3', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At 3,781 metres in the Huancavelica Region lies Wiraqucha Pirqa, Quechua for wall of Viracocha: a little pre-Hispanic town and a stone forest whose caves hold cave paintings."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is at a height of 3,781 metres [S2]; it is in the Huancavelica Region [S2]; the name is Quechua for wall of Viracocha [S1]; there is a little pre-Hispanic town [S3]; there is a stone forest with caves [S3]; the caves contain cave paintings [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Wiraqucha Pirqa is an archaeological site with a little pre-Hispanic town, in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_Pirqa]; It lies in the Huancavelica Region [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_Pirqa]; It lies at 3,781 metres [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_Pirqa]; Wiraqucha Pirqa is Quechua for wall of Viracocha [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_Pirqa]; The site includes a stone forest [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_Pirqa]; The stone forest''s caves hold cave paintings [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_Pirqa]"}]'::jsonb),
    ('fabd8d1b-1a9c-4266-8ff6-d764c6229943'::uuid, 'card_description', 'A 3rd–4th century villa in the Loures municipality within Roman Olisipo''s territory. Excavations since 1997 have traced its reuse into the medieval Islamic period; classified heritage since 2012.', 'Fragments of Roman mosaics surfaced near the Chapel of Santa Catarina at the Roman Villa of Frielas in Loures, once in the territory of Olisipo, which stretched from Lisbon to Torres Vedras.', 'teaser-card-s006:fabd8d1b-1a9c-4266-8ff6-d764c6229943:card_description', 'teaser-card-s006 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '0c34295267f869d28c4805f581ca7d66774d715cbaf65e1b44df1e3e49756e40|f58e629770717190fcd0c62d6168b5802c0934a6af38bee9589d45b09f94a69d|f58e629770717190fcd0c62d6168b5802c0934a6af38bee9589d45b09f94a69d', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Fragments of Roman mosaics surfaced near the Chapel of Santa Catarina at the Roman Villa of Frielas in Loures, once in the territory of Olisipo, which stretched from Lisbon to Torres Vedras."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "fragments of Roman mosaics were discovered [S5]; they were found near the Chapel of Santa Catarina [S5]; they were found at the Roman Villa of Frielas [S5]; the villa is in Loures [S1]; the villa fell under the territory of Olisipo [S2]; Olisipo''s territory stretched from Lisbon to Torres Vedras [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Roman Villa of Frielas is a Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]; The villa lies in Loures [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]; Fragments of Roman mosaics surfaced at the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]; The mosaic fragments were found near the Chapel of Santa Catarina [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]; The villa was once in the territory of Olisipo [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]; The territory of Olisipo reached Lisbon [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]; The territory of Olisipo stretched to Torres Vedras [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Frielas]"}]'::jsonb),
    ('fadd9ef3-4d6a-4a8b-8b2a-250388ee531d'::uuid, 'card_description', 'Although best known for its role as an important early Celtic centre from the 7th to 5th centuries BC, the Heuneburg was occupied at several other points during its history.', 'On a spur rising steeply 40 m above the Danube stood the fortified citadel of the Heuneburg, about 300 by 150 m, an important early Celtic centre from the 7th to 5th centuries BC.', 'teaser-card-s006:fadd9ef3-4d6a-4a8b-8b2a-250388ee531d:card_description', 'teaser-card-s006 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '073dac1f97adad736e7eb31a26e42e0ecee0a496e6b129769248bccbfdaa8bc1|eb704871d2ef9dbca76c439ab5f7a37435fbc19a5c832ab4c3d2345a649c3dc4|eb704871d2ef9dbca76c439ab5f7a37435fbc19a5c832ab4c3d2345a649c3dc4', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a spur rising steeply 40 m above the Danube stood the fortified citadel of the Heuneburg, about 300 by 150 m, an important early Celtic centre from the 7th to 5th centuries BC."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the citadel stood on a spur rising steeply 40 m above the Danube [S5]; the Heuneburg had a fortified citadel [S3, S4]; the citadel measures about 300 by 150 m [S4]; it was an important early Celtic centre [S2, S6]; that role dates from the 7th to 5th centuries BC [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Heuneburg is a prehistoric Celtic hillfort (fortified site) by the Danube, in Germany [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]; The Heuneburg had a fortified citadel [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]; The citadel stood on a spur [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]; The spur rises steeply 40 m above the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]; The citadel measures about 300 by 150 m [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]; The Heuneburg was an important early Celtic centre [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]; It was an important early Celtic centre from the 7th to the 5th centuries BC [SUPPORTED: https://en.wikipedia.org/wiki/Heuneburg]"}]'::jsonb),
    ('fb563088-580b-4d87-8c51-8934659a5d31'::uuid, 'card_description', 'A Minoan palace city from the 4th millennium BC, the second-largest on Crete after Knossos. The famous Phaistos Disc, with its undeciphered spiral script, was found here.', 'In south central Crete lie the remains of the Minoan palace of Phaistos, first built around 2000 BCE, then destroyed and rebuilt three times in a period of about three centuries.', 'teaser-card-s006:fb563088-580b-4d87-8c51-8934659a5d31:card_description', 'teaser-card-s006 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '9b3bb8e388498681e3ad87385a886c1662dad74d88bb81907c7c526e8df8eee4|bc60d3808dadc12f26062721cbc4ce805c852c0cf73417c0ceddc16153704c49|bc60d3808dadc12f26062721cbc4ce805c852c0cf73417c0ceddc16153704c49', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In south central Crete lie the remains of the Minoan palace of Phaistos, first built around 2000 BCE, then destroyed and rebuilt three times in a period of about three centuries."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Phaistos is in south central Crete [S1]; it has the remains of a Minoan palace [S2]; the palace was first built around 2000 BCE [S4]; the palace was destroyed and rebuilt three times [S5]; this happened in a period of about three centuries [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Phaistos is the site of the remains of a Minoan palace [SUPPORTED: https://en.wikipedia.org/wiki/Phaistos]; Phaistos lies in south central Crete [SUPPORTED: https://en.wikipedia.org/wiki/Phaistos]; The palace was first built around 2000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Phaistos]; The palace was then destroyed and rebuilt three times [SUPPORTED: https://en.wikipedia.org/wiki/Phaistos]; The destructions and rebuildings took place within a period of about three centuries [SUPPORTED: https://en.wikipedia.org/wiki/Phaistos]"}]'::jsonb),
    ('fc247379-6a08-4cca-bd66-ff2c661e6c00'::uuid, 'card_description', 'A small circular ringfort, or ''round,'' with a single entrance and enclosing bank. Hundreds of these compact defensive homesteads dot the Cornish landscape from the Iron Age onward.', 'On a hilltop about 1 mile west of Penzance, the circular bank of Lesingey Round encloses about 1.5 acres. No trace of occupation shows inside, and no one knows where the entrance was.', 'teaser-card-s006:fc247379-6a08-4cca-bd66-ff2c661e6c00:card_description', 'teaser-card-s006 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '19a47239469b1fecf168d41c635652ec3999cef711d5a0b78f3693f543bb783e|3769cd663bb8285f2391052f7e287ff4bcf74f8b5d1fbbfe0e84e35081b6a390|3769cd663bb8285f2391052f7e287ff4bcf74f8b5d1fbbfe0e84e35081b6a390', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a hilltop about 1 mile west of Penzance, the circular bank of Lesingey Round encloses about 1.5 acres. No trace of occupation shows inside, and no one knows where the entrance was."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Lesingey Round is on a hilltop [S3]; it is about 1 mile west of Penzance [S1]; it has a circular bank [S4]; the bank encloses about 1.5 acres [S4]; no trace of occupation is visible inside [S6]; the location of the entrance is not known [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Lesingey Round is a round, an embanked circular enclosure (ringfort) near Penzance [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]; It lies on a hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]; It lies about 1 mile west of Penzance [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]; Its bank is circular [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]; The bank encloses about 1.5 acres [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]; No trace of occupation shows inside [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]; No one knows where the entrance was [SUPPORTED: https://en.wikipedia.org/wiki/Lesingey_Round]"}]'::jsonb),
    ('fc4bf634-d20e-4c83-b72a-5b3a69d9ed59'::uuid, 'card_description', 'A Roman villa perched on a clifftop with views across the Channel to the French coast. Human activity at the site goes back thousands of years before the Romans arrived.', 'On a cliff top above the English Channel, Folkestone Roman Villa rose around A. D. 75. Remains beneath it suggest Iron Age querns, grinding stones, were made on an almost industrial scale.', 'teaser-card-s006:fc4bf634-d20e-4c83-b72a-5b3a69d9ed59:card_description', 'teaser-card-s006 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7d8e7533c3090c86ed9f62e24140ee17dff462155e4eccb7238224713cca2139|f0dee78c33f14c64e089f02b7839ad25d21623acf503b38ee104cb390e9e012c|f0dee78c33f14c64e089f02b7839ad25d21623acf503b38ee104cb390e9e012c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a cliff top above the English Channel, Folkestone Roman Villa rose around A. D. 75. Remains beneath it suggest Iron Age querns, grinding stones, were made on an almost industrial scale."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the villa is on a cliff top above the English Channel [S2]; the villa was built around A. D. 75 [S3]; remains beneath the villa suggest querns were made there in the Iron Age [S6]; querns are grinding stones [S6]; the quern production was on an almost industrial scale (as a suggestion) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Folkestone Roman Villa is a Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]; It stands on a cliff top above the English Channel [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]; The villa rose around A.D. 75 [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]; Remains beneath the villa point to quern production at the site [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]; Querns are grinding stones [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]; The querns were made in the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]; The querns were made on an almost industrial scale [SUPPORTED: https://en.wikipedia.org/wiki/Folkestone_Roman_Villa]"}]'::jsonb),
    ('fc9edb4c-80d3-4046-a92b-2a0137c419cf'::uuid, 'card_description', 'A megalithic stone circle smashed by a farmer with a sledgehammer in the 1870s. Before its destruction, it was a druidical ritual site beside a Roman road.', 'The stone circle of Cheetham Close, about 18.5 metres in diameter, was in good condition until a farmer from Turton took a sledgehammer to it in the 1870s. Its stones now lie fractured.', 'teaser-card-s006:fc9edb4c-80d3-4046-a92b-2a0137c419cf:card_description', 'teaser-card-s006 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '39783b05f764f0115df774b113cdd3167edebb23c70b48447ff133b8e560d574|df929e2ade07100f46f634499a25fd5b4c534457fed2b493ca73429d0330fec1|df929e2ade07100f46f634499a25fd5b4c534457fed2b493ca73429d0330fec1', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The stone circle of Cheetham Close, about 18.5 metres in diameter, was in good condition until a farmer from Turton took a sledgehammer to it in the 1870s. Its stones now lie fractured."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cheetham Close is a stone circle [S3]; the circle measured about 18.5 metres in diameter [S3]; it was in good condition until the 1870s [S2]; a farmer from Turton sledgehammered it in the 1870s [S2]; its stones are fractured [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cheetham Close is a stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]; The circle is about 18.5 metres in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]; The circle was in good condition until it was damaged [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]; The damage was done by a farmer from Turton [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]; The farmer took a sledgehammer to the circle [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]; This happened in the 1870s [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]; Its stones now lie fractured [SUPPORTED: https://en.wikipedia.org/wiki/Cheetham_Close]"}]'::jsonb),
    ('ffdc79c0-d3da-413f-9d4d-114a0719585c'::uuid, 'card_description', 'According to Pausanias, the ancient theatre was constructed at the end of the 4th century BC, circa 340-300 BCE, by the architect Polykleitos the Younger.', 'On Cynortion Mountain, the Ancient Theatre of Epidaurus could hold 13,000 to 14,000 spectators for the music, singing and dramatic games staged in the worship of Asclepius, god of medicine.', 'teaser-card-s006:ffdc79c0-d3da-413f-9d4d-114a0719585c:card_description', 'teaser-card-s006 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'daa724b7fb30d5c9806cda4e0d8a5e04a86c9ef8986bac86f62c052c91990175|28e9cc65df3245909f5ed45bf4256c9c80b19371cbdb094bc27fb0097fd808c6|28e9cc65df3245909f5ed45bf4256c9c80b19371cbdb094bc27fb0097fd808c6', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On Cynortion Mountain, the Ancient Theatre of Epidaurus could hold 13,000 to 14,000 spectators for the music, singing and dramatic games staged in the worship of Asclepius, god of medicine."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the theatre is on Cynortion Mountain [S2]; it could hold 13,000 to 14,000 spectators [S4]; it hosted music, singing and dramatic games [S4]; these were part of the worship of Asclepius [S4]; Asclepius was the god of medicine [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Ancient Theatre of Epidaurus is an ancient Greek theatre [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Epidaurus]; It lies on Cynortion Mountain [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Epidaurus]; It could hold 13,000 to 14,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Epidaurus]; Music, singing and dramatic games were staged there [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Epidaurus]; These games were staged in the worship of Asclepius [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Epidaurus]; Asclepius was the god of medicine [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Epidaurus]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 50;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s006', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s006'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s006'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 50 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s006'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s006' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
